import{_ as a,o as e,c as i,a5 as r}from"./chunks/framework.bIR-4glx.js";const f=JSON.parse('{"title":"英语能力诊断｜找到可复测的起点","description":"面向想提升工作与日常英语的自学者，先用五分钟保存一项英语基线，再按需完成听说读写完整诊断，记录障碍并安排十四天后的平行任务复测。","frontmatter":{"title":"英语能力诊断｜找到可复测的起点","description":"面向想提升工作与日常英语的自学者，先用五分钟保存一项英语基线，再按需完成听说读写完整诊断，记录障碍并安排十四天后的平行任务复测。","updated":"2026-10-19T00:00:00.000Z","topic":"english-learning","intent":"diagnostic","schema":"Article","socialImage":"/assets/social/english-zh.png","socialImageAlt":"英语能力诊断与复测入口分享图"},"headers":[],"relativePath":"topics/english-diagnostic.md","filePath":"topics/english-diagnostic.md","lastUpdated":1792368000000}'),d={name:"topics/english-diagnostic.md"};function l(n,t,s,o,h,c){return e(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="英语能力诊断-找到可复测的起点" tabindex="-1">英语能力诊断：找到可复测的起点 <a class="header-anchor" href="#英语能力诊断-找到可复测的起点" aria-label="Permalink to &quot;英语能力诊断：找到可复测的起点&quot;">​</a></h1><p>如果你搜索的是英语水平测试、CEFR 自测或工作英语提升，先把抽象的“水平”变成一段能保存的证据。诊断的结果不是标签，而是下一项值得修复的障碍。</p><h2 id="适合谁" tabindex="-1">适合谁 <a class="header-anchor" href="#适合谁" aria-label="Permalink to &quot;适合谁&quot;">​</a></h2><ul><li>想知道听、说、读、写目前分别卡在哪里的人。</li><li>需要英语支持远程协作、面试、技术文档或客户沟通的人。</li><li>试过背词或刷题，却无法判断真实工作是否变好的学习者。</li></ul><h2 id="五分钟先留一项基线" tabindex="-1">五分钟先留一项基线 <a class="header-anchor" href="#五分钟先留一项基线" aria-label="Permalink to &quot;五分钟先留一项基线&quot;">​</a></h2><p>这一步只检查一项能力，不等于 CEFR 定级，也不等于完整的听说读写诊断。选一个近期真实会用到的主题，设五分钟计时器，完成下面一项：</p><table tabindex="0"><thead><tr><th>选择</th><th>五分钟任务</th><th>保存的证据</th></tr></thead><tbody><tr><td>听力</td><td>听一段 60–90 秒音频一次</td><td>写一句主旨和一个听到的细节</td></tr><tr><td>阅读</td><td>阅读一段约 150–250 词的材料</td><td>写一句主张和一个支持它的证据</td></tr><tr><td>口语</td><td>不看稿录一段 60 秒说明</td><td>保存原录音，并标记一次停顿或说不清之处</td></tr><tr><td>写作</td><td>用五分钟写一条真实工作或生活消息</td><td>保存原稿，并圈出一个不确定的表达或事实</td></tr></tbody></table><p>先不要用 AI 润色。写下具体卡点，例如漏听了词间连接、找不到证据、表达中断，或读者不知道下一步。把样本私下保存，选择一个卡点练习；十四天后换一个相近主题复测。</p><h2 id="完整诊断" tabindex="-1">完整诊断 <a class="header-anchor" href="#完整诊断" aria-label="Permalink to &quot;完整诊断&quot;">​</a></h2><p>需要判断听说读写分别卡在哪里时，再做完整诊断。它明显超过五分钟：模板建议听 2–4 分钟音频、阅读 600–1000 词、录制 2 分钟口语，并用 20 分钟完成写作，再比较条件、错误和迁移表现。复制<a href="./../templates/english-diagnostic">英语能力诊断工作表</a>，不要用单项样本推断整体等级。</p><h2 id="三步继续" tabindex="-1">三步继续 <a class="header-anchor" href="#三步继续" aria-label="Permalink to &quot;三步继续&quot;">​</a></h2><ol><li>先看 <a href="./../threads/part-1/0-cefr">CEFR 目标与自测</a>，选择一个近期会用到的真实主题。</li><li>若要继续完整诊断，用 <a href="./../templates/english-diagnostic">英语能力诊断</a> 保存四项首版样本，再按需查看 <a href="./../templates/listening-audit">听力证据卡</a>、<a href="./../templates/speaking-evidence">口语证据卡</a>、<a href="./../templates/reading-evidence">阅读证据卡</a> 或 <a href="./../templates/writing-evidence">写作证据卡</a>。</li><li>记录一个最小障碍，练习十四天，在不同材料或不同对话对象上复测；把可见变化放进 <a href="./../templates/evidence-chain">证据链模板</a>。</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>不要把诊断变成一次考试。先保存一份不借助 AI 的样本，再用 AI 解释错误、生成练习或模拟对话，最后由你确认含义和可迁移性。完成首轮诊断后，可以进入 <a href="./../recent-updates">最近更新</a> 或 <a href="./ai-learning-workflows">AI 学习工作流入口</a>。</p>',14)])])}const g=a(d,[["render",l]]);export{f as __pageData,g as default};
